/// <summary>
/// COC of PurchLine table
/// </summary>
[ExtensionOf(tablestr(PurchLine))]
final class METPurchLine_Extension
{
}

Method.Source:
    /// <summary>
    /// Performs specific actions when a field is modified.
    /// </summary>
    /// <param name="_fieldId">
    /// The field ID of the field that has been modified.
    /// </param>
    /// <param name="_userInput">
    /// A Boolean value indicating whether the field change is initiated through direct user input; optional.
    /// </param>
    /// <remarks>
    /// This is overridden to allow for specific actions when a field is modified.
    /// </remarks>
    public void modifiedField(FieldId _fieldId, boolean _userInput)
    {        
        InventItemPurchSetup    metinventItemPurchSetupStd;

        next  modifiedField(_fieldId, _userInput);

        switch (_fieldId)
        {
            case fieldNum(PurchLine, ItemId):
                
                metinventItemPurchSetupStd = InventItemPurchSetup::find(this.Itemid,this.InventdimId);
                  
                if (metinventItemPurchSetupStd.METPurchUnit)
                {
                    this.PurchUnit = metinventItemPurchSetupStd.METPurchUnit;                    
                }

                break;
        }
    }

    /// <summary>
    /// Cancel purchase order line
    /// </summary>
    public void metCancelPurchaseOrderLine()
    {
        PurchLine purchLine = PurchLine::findRecId(this.RecId, true);
        
        ttsbegin;
        purchLine.RemainInventPhysical       = 0;
        purchLine.RemainPurchPhysical        = 0;
        purchLine.PdsCWRemainInventPhysical  = 0;

        purchLine.update();
        ttscommit;
    }

/// <summary>
/// Get the MET purchase line
/// </summary>
/// <returns>METPurchLine</returns>
public METPurchLine metPurchLine()
{
    return this.SysExtensionSerializerMap::getExtensionTable(tableNum(METPurchLine));
}

    /// <summary>
    /// pack the METPurchLine
    /// </summary>
    /// <param name = "_metPurchLine">METPurchLine to pack</param>
    public void metPackMETPurchLine(METPurchLine  _metPurchLine)
    {
        _metPurchLine.PurchLine = this.RecId;

        this.SysExtensionSerializerMap::packExtensionTable(_metPurchLine);
    }

    /// <summary>
    /// Create a METPurchLine record
    /// </summary>
    /// <returns> record buffer </returns>
    public METPurchLine metCreateMETPurchLine()
    {
        METPurchLine metPurchLine;

        this.metPackMETPurchLine(metPurchLine);
        this.SysExtensionSerializerMap::postInsert();
        
        return this.metPurchLine();
    }

    /// <summary>
    /// Method to determine if conversion exists  between the purchase and warehouse units
    /// </summary>
    /// <param name = "_purchLine">the purchase line</param>
    /// <param name = "_inventLocationId">the warehouse location</param>
    /// <param name = "_inventSiteId">the inventory site</param>
    /// <returns>True if UOM conversion is found/else false and warehouse unit and the warehouse quantity</returns>
    public static container getWarehouseUnitAndQty(PurchLine _purchLine, InventLocationId _inventLocationId, InventSiteId _inventSiteId)
    {
        UnitOfMeasureConversion     unitOfMeasureConversion;
        boolean                     isUnitConversionPresent = true;
        UnitOfMeasureSymbol         purchUnit = _purchLine.PurchUnit;
        ItemId                      itemId = _purchLine.ItemId;
        Qty                         warehouseQty;
        InventTableModule           inventTableModule;
        UnitOfMeasureSymbol         inventoryUnit, warehouseUnit;
        PurchTable                  purchTable;
        InventLocationId            inventLocationIdLoc;
        InventLocation              inventLocation;
        METInventLocation           metInventLocation;
        METExtWMSUnit               externalWarehouseUnit;

        InventItemPurchSetup        inventItemPurchSetup;
        InventItemSalesSetup        inventItemSalesSetup;
        InventDim                   inventDim;

        inventLocationIdLoc = _inventLocationId;
        if(!inventLocationIdLoc)
        {
            select firstonly InventLocationId from purchTable
                where purchTable.PurchId == _purchLine.PurchId;

            inventLocationIdLoc = purchTable.InventLocationId;
            if(!inventLocationIdLoc)
            {
                warehouseUnit = purchUnit;
                warehouseQty = _purchLine.PurchQty;

                return [isUnitConversionPresent, warehouseQty, warehouseUnit];
            }
        }

        select firstonly ExternalWMSUnit from metInventLocation
            join RecId from inventLocation
                where metInventLocation.InventLocation == inventLocation.RecId
                    && inventLocation.InventLocationId == inventLocationIdLoc;

        externalWarehouseUnit = metInventLocation.ExternalWMSUnit;

        switch(externalWarehouseUnit)
        {
            case METExtWMSUnit::DefaultInventoryUnit :
                select firstonly UnitId from inventTableModule
                    where inventTableModule.ItemId      == itemId
                        && inventTableModule.ModuleType == ModuleInventPurchSales::Invent;

                if(inventTableModule.UnitId)
                {
                    warehouseUnit = inventTableModule.UnitId;
                }
                break;

            case METExtWMSUnit::DefaultPurchaseUnit :

                inventDim.clear();
                inventDim.InventSiteId = _inventSiteId;
                inventDim = InventDim::findDim(inventDim);

                inventItemPurchSetup = InventItemPurchSetup::find(itemId, inventDim.inventDimId);

                if(inventItemPurchSetup.METPurchUnit)
                {
                    warehouseUnit = inventItemPurchSetup.METPurchUnit;
                }
                break;

            case METExtWMSUnit::DefaultSellUnit :

                inventDim.clear();
                inventDim.InventSiteId = _inventSiteId;
                inventDim = InventDim::findDim(inventDim);

                inventItemSalesSetup = InventItemSalesSetup::find(itemId, inventDim.inventDimId);
                
                if(inventItemSalesSetup.METSalesUnit)
                {
                    warehouseUnit = inventItemSalesSetup.METSalesUnit;
                }
                break;

            default : 
                warehouseUnit = purchUnit;
                warehouseQty = _purchLine.PurchQty;
                return [isUnitConversionPresent, warehouseQty, warehouseUnit];
        }
             
        
        select firstonly UnitId from inventTableModule
            where inventTableModule.ItemId      == itemId
                && inventTableModule.ModuleType == ModuleInventPurchSales::Invent;

        if(inventTableModule.UnitId)
        {
            inventoryUnit = inventTableModule.UnitId;
        }

        if(purchUnit == warehouseUnit)
        {
            isUnitConversionPresent = true;
            warehouseQty = _purchLine.PurchQty;
        }
        else if(warehouseUnit != METConstants::emptyString)
        {
            unitOfMeasureConversion = UnitOfMeasureConversion::findByConversion(
                            UnitOfMeasure::findBySymbol(warehouseUnit).RecId,
                            UnitOfMeasure::findBySymbol(purchUnit).RecId,
                            EcoResProduct::findByProductNumber(_purchLine.ItemId).RecId);

            if(unitOfMeasureConversion.RecId)
            {
                isUnitConversionPresent = true;
                if(purchUnit == inventoryUnit)
                {
                    warehouseQty = _purchLine.PurchQty / unitOfMeasureConversion.Factor;
                }
                else
                {
                    warehouseQty = _purchLine.PurchQty * unitOfMeasureConversion.Factor;
                }
            }
            else
            {
                //Check purchase to warehouse conversion
                unitOfMeasureConversion = UnitOfMeasureConversion::findByConversion(
                            UnitOfMeasure::findBySymbol(purchUnit).RecId,
                            UnitOfMeasure::findBySymbol(warehouseUnit).RecId,
                            EcoResProduct::findByProductNumber(_purchLine.ItemId).RecId);

                if(unitOfMeasureConversion.RecId)
                {
                    isUnitConversionPresent = true;
                    if(purchUnit == inventoryUnit)
                    {
                        warehouseQty = _purchLine.PurchQty / unitOfMeasureConversion.Factor;
                    }
                    else
                    {
                        warehouseQty = _purchLine.PurchQty * unitOfMeasureConversion.Factor;
                    }
                }
                else
                {
                    isUnitConversionPresent = false;
                }
            }
        }

        return [isUnitConversionPresent, warehouseQty, warehouseUnit];
    }

    /// <summary>
    /// Inserts a table buffer into the database.
    /// </summary>
    /// <param name="dropInvent">
    /// A Boolean value that indicates whether the inventory movement that is associated with the line must
    /// be updated; optional; false by default.
    /// </param>
    /// <param name="findMarkup">If it is true, it finds makup</param>
    /// <param name="updatePurchTableDistributions">A Boolean value that indicates whether the purchtable distributions should be updated for all lines on the purchase order</param>
    /// <param name="_skipPurchTableUpdate">A Boolean value that indicates whether purchase table has to be updated</param>
    /// <param name="_skipInterCompanyCalcDisc">A Boolean value that indicates whether intercompany discounts should be calculated</param>
    public void insert(boolean     dropInvent,
        boolean     findMarkup,
        boolean     updatePurchTableDistributions,
        boolean     _skipPurchTableUpdate,
        boolean     _skipInterCompanyCalcDisc)
    {
        InventDim       inventDim = InventDim::find(this.InventDimId);
        InventDim       inventDimLoc;
        InventBatch     inventBatch;
        METPurchLine    metPurchLine;
        InventLocation  inventLocation = InventLocation::find(inventDim.InventLocationId);
        
        //NS-Added for the bug 187793: Batch number not populating on the intercompany sales order line and sales order not auto extracting

        inventDimLoc.InventSiteId       = inventDim.InventSiteId;
        inventDimLoc.InventLocationId   = inventDim.InventLocationId;
        
        // Task 246314 : Defualt the wms location based on the EventID in the purchase table start
        if (this.purchTable().metPurchTable().EventID)
        {
            inventDimLoc.wMSLocationId = inventLocation.METWMSDefaultEventLocationId;
        }
        else
        {
            inventDimLoc.wMSLocationId = inventLocation.WMSLocationIdDefaultReceipt;
        }
        if (InventTable::find(this.ItemId).isItemBatchActivated()) // modified this line to consider batch update only if item has active batch id enabled
        {
            select firstonly InventBatchId from inventBatch where inventBatch.itemId == this.ItemId;
            if (inventBatch.inventBatchId)
            {
                inventDimLoc.inventBatchId = inventBatch.inventBatchId;
            }
        }
        // Task 246314 end

        inventDimLoc = InventDim::findOrCreate(inventDimLoc);

        this.InventDimId = inventDimLoc.inventDimId;
        //NE-Added for the bug 187793: Batch number not populating on the intercompany sales order line and sales order not auto extracting
        
        PurchTable purchTableLoc = this.purchTable();

        if (purchTableLoc.METIntercompanyTransferReplenishment || purchTableLoc.InterCompanyOrigin == InterCompanyOrigin::Derived)
        { 
            SalesLine salesLine = this.salesLine();

            if (salesLine.RecId)
            {
                this.PurchUnit = salesLine.SalesUnit;
            }

            [this.BarCode, this.BarCodeType] = this.metGetBarCodeForIntercompanyPurchLines(null);
            this.LineAmount = this.calcLineAmountForcedInteraction(fieldNum(PurchLine, PurchPrice));
            this.PurchPrice = this.metGetUnitPriceForIntercompanyPurchLines(null);
        }

        next insert(dropInvent,
                    findMarkup,
                    updatePurchTableDistributions,
                    _skipPurchTableUpdate,
                    _skipInterCompanyCalcDisc);

        metPurchLine = this.metPurchLine();
        
        if (metPurchLine.RecId == 0)
        {
            this.metPackMETPurchLine(metPurchLine);
            this.SysExtensionSerializerMap::postInsert();
        }

        // Calculate and set the PurchaseWMSFactor if not already set
        //Added for Bug 317591: Full SIT :- CB336 :- Purchase Order Purchase WMS Factor becoming Zero in D365
        if (!metPurchLine.PurchaseWMSFactor && inventLocation.RecId)
        {
            METInventLocation   metInventLocation;

            select firstonly ExternalWMSUnit from metInventLocation               
                where metInventLocation.InventLocation == inventLocation.RecId;
               

            metPurchLine.PurchaseWMSFactor =  METPurchTableFormEventHandler::processPurchaseWMSFactor(metInventLocation.ExternalWMSUnit, this);
        }
    }

    /// <summary>
    /// Updates a table buffer into the database.
    /// </summary>
    /// <param name="dropInvent">
    /// A Boolean value that indicates whether the inventory movement that is associated with the line must
    /// be updated; optional; false by default.
    /// </param>
    /// <param name="updateOrderLineOfDeliverySchedule">
    /// A Boolean value that indicates whether to update the order line after updating its delivery line;
    /// optional; true by default. Parameter is obsolete.
    /// </param>
    /// <param name="updatePurchTableDropShipStatus">
    /// A Boolean value that indicates whether the drop shipment status should be updated for all lines on the purchase order;
    /// optional; true by default.
    /// </param>
    public void update(boolean  dropInvent,
                       boolean  updateOrderLineOfDeliverySchedule,
                       boolean  updatePurchTableDropShipStatus)
    {
        next update(dropInvent,
                    updateOrderLineOfDeliverySchedule,
                    updatePurchTableDropShipStatus);

        this.SysExtensionSerializerMap::postUpdate();
    }

/// <summary>
/// copies proifit centredimension from warehouse 
/// </summary>
/// <param name = "_inventDim">InventDim record</param>
public void metCopyDimensionfromWarehosue(InventDim _inventDim = this.inventDim())
{
    DimensionDefault            dimensionWarehouse;
    //Copy dimension from Warehouse if exists
    if (_inventDim.InventLocationId)
    {
        dimensionWarehouse = InventLocation::changeDimension(this.DefaultDimension, _inventDim.InventLocationId);
    }
    DimensionDisplayValue dimensionValue = METHelper::getDimensionValue(dimensionWarehouse, METConstants::profitCentre);
    if(dimensionValue)
    {
        this.DefaultDimension = dimensionWarehouse;
    }
    else
    {
        this.DefaultDimension = InventSite::changeDimension(this.DefaultDimension, _inventDim.InventSiteId);
    }
}

    /// <summary>
    /// Method get the aggregated or summed received quantities for each Item and purchase unit for each of unique combination of Site and Warehouse. 
    /// </summary>
    /// <returns>Returns the summed quantity for each item received from Vendors at unique site and warehouse</returns>
    public Qty metReceiptedWarehouseQty()
    {
        Qty                     totalQty;
        VendPackingSlipTrans    vendPackingSlipTrans;
        InventDim               inventDim;

        while select PurchUnit, ItemId, sum(Qty) from vendPackingSlipTrans
                group by PurchUnit, ItemId
                where vendPackingSlipTrans.InventTransId == this.InventTransId
            join InventLocationId, InventSiteId from inventDim
                group by InventLocationId, InventSiteId
                where inventDim.inventDimId == vendPackingSlipTrans.InventDimId   
        {
            totalQty += conPeek(InventTable::getWarehouseUnitAndQty(vendPackingSlipTrans.Qty, vendPackingSlipTrans.PurchUnit, 
                                                            vendPackingSlipTrans.ItemId, inventDim.InventLocationId, 
                                                            inventDim.InventSiteId), 2);
        }

        return totalQty;
    }

    /// <summary>
    /// VM - CB219 - PO Acknowledgement remove fields
    /// Validated in case the itemId selected is custom/Excise or viceversa
    /// </summary>
    /// <returns>boolean</returns>
    public boolean validateWrite()
    {
        boolean ret = next validateWrite();

        METInventtable metInventtable = METInventtable::find(this.ItemId);
        METPurchTable metPurchTable = METPurchTable::find(this.PurchId);        

        if (metInventtable.RecId && metPurchTable.RecId)
        {
            boolean isTariffExcise = metInventtable.METTariffItemCodeBaseRecid;
            boolean isBondPO = metPurchTable.UnderBond;

            if ((isBondPO && !isTariffExcise) || (!isBondPO && isTariffExcise))
            {
                ret = checkFailed("@MET:CustomItemValidate");
            }
        }

        if (this.purchTable().METIntercompanyTransferReplenishment || this.purchTable().InterCompanyOrigin == InterCompanyOrigin::Derived)
        {
            if (this.BarCode == '')
            {
                warning("@MET:MatchingBarcodeForICLineNotFound");
            }

            if (!this.PurchPrice)
            {
                warning("@MET:MatchingUnitPriceForICLineNotFound");
            }
        }

        return ret;
    }

    /// <summary>
    ///  Handles the event when the item changes.
    ///  Method to determine and set the bar code and unit price for active purchase line when the order Item is modified and purcahse order being Intercompany replenishment transfer enabled.
    /// </summary>
    /// <param name = "_matchingAgreement">The <c>RecId</c> of the matching agreement.</param>
    /// <param name="_executeOnlyIfProductIsFullySpecified">
    ///     A Boolean value indicating whether to perform product variant validation; optional.
    /// </param>
    public void itemIdChanged(AgreementHeaderRecId _matchingAgreement, boolean _executeOnlyIfProductIsFullySpecified)
    {
        next itemIdChanged(_matchingAgreement, _executeOnlyIfProductIsFullySpecified);

        METPurchLine metPurchLine = this.metPurchLine();
        metPurchLine.InventItemBasePrice = this.metCalcInventItemBasePrice();
        this.metPackMETPurchLine(metPurchLine);

        if ((this.purchTable().METIntercompanyTransferReplenishment || this.purchTable().InterCompanyOrigin == InterCompanyOrigin::Derived)
            && this.ItemId && this.InventDimId && this.PurchUnit )
        {
            ReqItemTable reqItemTable = ReqItemTable::metFindReqItemTable(this.ItemId, this.InventDimId);

            if (reqItemTable)
            {
                [this.BarCode, this.BarCodeType] = this.metGetBarCodeForIntercompanyPurchLines(reqItemTable);
                this.PurchPrice = this.metGetUnitPriceForIntercompanyPurchLines(reqItemTable);
                this.LineAmount = this.calcLineAmountForcedInteraction(fieldNum(PurchLine, PurchPrice));
            }
            else
            {
                this.BarCode = '';
                this.BarCodeType = '';
                this.PurchPrice = 0.00;
                this.LineAmount = 0.00;
            }
        }
    }

    /// <summary>
    /// Changes the purchase line based on changes in the <c>PurchUnit</c> field.
    /// </summary>
    /// <remarks>
    /// This method is called from the <c>modifiedField</c> method.
    /// </remarks>
    public void purchUnitModified()
    {
        next purchUnitModified();

        InventItemBarcode   inventItemBarcode = InventItemBarcode::metFindPurchBarcodeDimension(this.ItemId, this.inventDim(), '', this.PurchUnit, this.VendAccount);
       
        this.BarCode        = inventItemBarcode.ItemBarCode;
        this.BarCodeType    = inventItemBarcode.BarcodeSetupId;

        if ((this.purchTable().METIntercompanyTransferReplenishment || this.purchTable().InterCompanyOrigin == InterCompanyOrigin::Derived)
            && this.ItemId && this.PurchUnit)
        {
            ReqItemTable reqItemTable = ReqItemTable::metFindReqItemTable(this.ItemId, this.InventDimId);
                
            if (reqItemTable)
            {
                [this.BarCode, this.BarCodeType] = this.metGetBarCodeForIntercompanyPurchLines(reqItemTable);
                this.PurchPrice = this.metGetUnitPriceForIntercompanyPurchLines(reqItemTable);
                this.LineAmount = this.calcLineAmountForcedInteraction(fieldNum(PurchLine, PurchPrice));
            }
            else
            {
                this.BarCode = '';
                this.BarCodeType = '';
                this.PurchPrice = 0.00;
                this.LineAmount = 0.00;
            }
        }
    }

    /// <summary>
    /// Method to initialise barcode details.
    /// </summary>
    /// <param name = "_inventDim">Inventory dimension id</param>
    void initBarcode(InventDim _inventDim)
    {
        next initBarcode(_inventDim);

        SalesLine salesLine = this.salesLine();

        InventItemBarcode inventItemBarcode = InventItemBarcode::metFindPurchBarcodeDimension(this.ItemId, _inventDim, '', this.PurchUnit, this.VendAccount);

        this.BarCode        = inventItemBarcode.ItemBarCode;
        this.BarCodeType    = inventItemBarcode.BarcodeSetupId;

        if (this.purchTable().METIntercompanyTransferReplenishment || this.purchTable().InterCompanyOrigin == InterCompanyOrigin::Derived)
        {
            if (salesLine.RecId)
            {
                this.PurchUnit = salesLine.SalesUnit;
            }

            ReqItemTable reqItemTable = ReqItemTable::metFindReqItemTable(this.ItemId, this.InventDimId);

            if (reqItemTable)
            {
                [this.BarCode, this.BarCodeType] = this.metGetBarCodeForIntercompanyPurchLines(reqItemTable);
            }
            else
            {
                this.BarCode     = '';
                this.BarCodeType = '';
            }
        }
    }

    /// <summary>
    /// Updates the related fields when an inventory dimension field is modified.
    /// </summary>
    /// <param name="_inventDim">
    /// The new inventory dimension record.
    /// </param>
    /// <param name="_dimFieldId">
    /// The ID of the modified <c>InventDim</c> field.
    /// </param>
    /// <param name="_resetPrice">
    /// A Boolean value that indicates whether the price agreements are to be reset; optional.Default value is TRUE.
    /// </param>
    /// <returns>
    /// true if the inventory dimensions was modified; Otherwise false.
    /// </returns>
    public boolean modifyInventDim(
        InventDim   _inventDim,
        FieldId     _dimFieldId,
        boolean     _resetPrice)
    {
        boolean ret;

        ret = next modifyInventDim(_inventDim, _dimFieldId,  _resetPrice);

        if (ret && this.ItemId)
        {
            METPurchLine metPurchLine = this.metPurchLine();
            metPurchLine.InventItemBasePrice = this.metCalcInventItemBasePrice();
            this.metPackMETPurchLine(metPurchLine);
        }

        if (ret
            && (this.purchTable().METIntercompanyTransferReplenishment || this.purchTable().InterCompanyOrigin == InterCompanyOrigin::Derived)
            && this.ItemId 
            && this.PurchUnit)
        {
            ReqItemTable reqItemTable = ReqItemTable::metFindReqItemTable(this.ItemId, this.InventDimId);
            
            if (reqItemTable)
            {
                [this.BarCode, this.BarCodeType] = this.metGetBarCodeForIntercompanyPurchLines(reqItemTable);
                this.PurchPrice = this.metGetUnitPriceForIntercompanyPurchLines(reqItemTable);
                this.LineAmount = this.calcLineAmountForcedInteraction(fieldNum(PurchLine, PurchPrice));
            }
            else
            {
                this.BarCode = '';
                this.BarCodeType = '';
                this.PurchPrice = 0.00;
                this.LineAmount = 0.00;
            }
        }

        return ret;
    }

    private CostPriceNonMonetary metCalcInventItemBasePrice()
    {
        CostPriceNonMonetary   basePrice;
        GUPItemBasePrice        gupItemBasePrice;
        InventDim               siteOnlyInventDimCriteria;
        InventDim               siteOnlyInventDim;

        if (this.ItemId && this.InventDimId)
        {
            siteOnlyInventDimCriteria.InventSiteId = InventDim::find(this.InventDimId).InventSiteId;
            siteOnlyInventDim = InventDim::findDim(siteOnlyInventDimCriteria);

            TransDate activationDate = this.purchTable().DeliveryDate ? this.purchTable().DeliveryDate : DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());

            gupItemBasePrice = GUPItemBasePrice::findCurrent(
                this.ItemId,
                GUPBasePriceType::BasePriceInventoryCost,
                siteOnlyInventDim.InventDimId,
                dateNull(),
                this.VendAccount,
                activationDate);

            if (gupItemBasePrice)
            {
                basePrice = gupItemBasePrice.Price;
            }
        }

        return basePrice;
    }

    /// <summary>
    /// Gets unit price for an intercompany replenishment transfer enalbed purchase order line. Uses Item coverage's vendor account to fetch Item Base price value.
    /// </summary>
    /// <param name = "_common">Variable of type Common</param>
    /// <returns>Unit price for the line </returns>
    public PurchPrice metGetUnitPriceForIntercompanyPurchLines(Common _common)
    {
        ReqItemTable reqItemTable;
        GUPItemBasePrice itemBasePrice;
        PurchPrice purchPrice = 0.00;
        UnitOfMeasureConversionFactor factor = 1;

        if (_common && _common.TableId == tableNum(ReqItemTable))
        {
            reqItemTable = _common;
        }
        else
        {
            reqItemTable = ReqItemTable::metFindReqItemTable(this.ItemId, this.InventDimId);
        }

        InventSiteId inventSiteId = InventDim::find(this.InventDimId).InventSiteId;

        itemBasePrice = GUPItemBasePrice::metFindCurrentBasePriceForICReplenishTransferPurchLines(
            this.ItemId,
            GUPBasePriceType::BasePricePurchase,
            this.InventDimId,
            dateNull(),
            reqItemTable.VendId,
            this.PurchUnit,
            DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()),
            inventSiteId);

        if (itemBasePrice)
        {
            purchPrice = itemBasePrice.Price;
            return purchPrice;
        }
        else
        {
            if (this.PurchUnit != METConstants::UnitIdEA && !itemBasePrice)
            {
                itemBasePrice = GUPItemBasePrice::metFindCurrentBasePriceForICReplenishTransferPurchLines(
                    this.ItemId,
                    GUPBasePriceType::BasePricePurchase,
                    this.InventDimId,
                    dateNull(),
                    reqItemTable.VendId,
                    METConstants::UnitIdEA,
                    DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()),
                    inventSiteId );

                if (itemBasePrice && itemBasePrice.Price)
                {
                    factor = UnitOfMeasureConversion::findByConversion(
                            UnitOfMeasure::findBySymbol(this.PurchUnit).RecId,
                            UnitOfMeasure::findBySymbol(METConstants::UnitIdEA).RecId,
                            EcoResProduct::findByProductNumber(this.ItemId).RecId
                            ).Factor;

                    purchPrice = itemBasePrice.Price * factor;
                }
            }
           
            return purchPrice;
        }
    }

    /// <summary>
    /// Gets barcode for an intercompany purchase order line. Uses Item coverage vendor account to fetchbarcode aloing with other purchase line details.
    /// </summary>
    /// <param name = "_common">Variable of type Common</param>
    /// <returns>A container with barcode and barcode setup Id</returns>
    public container metGetBarCodeForIntercompanyPurchLines(Common _common)
    {
        ReqItemTable reqItemTable;
        InventItemBarcode inventItemBarCode;
        
        if (_common && _common.TableId == tableNum(ReqItemTable))
        {
            reqItemTable = _common;
        }
        else
        {
            reqItemTable = ReqItemTable::metFindReqItemTable(this.ItemId, this.InventDimId);
        }

        inventItemBarCode = InventItemBarcode::metFindByPruchLineDetails(this, reqItemTable.VendId);

        return [inventItemBarCode.itemBarCode, inventItemBarCode.barcodeSetupId];
    }

    /// <summary>
    /// Recalculate the unit price for purchase order enabled as Intercompany replenishment transfer.
    /// </summary>
    /// <param name = "_salesPurchLine">Map variable as purchLine</param>
    /// <returns>A container with calculated unit price and line amount for the purchase line</returns>
    public container metOverwriteSetPriceDisc(SalesPurchLine _salesPurchLine)
    {
        if (_salesPurchLine.TableId == tableNum(PurchLine))
        {
            PurchLine purchLine = _salesPurchLine as PurchLine;
            if (purchLine.purchTable().METIntercompanyTransferReplenishment|| this.purchTable().InterCompanyOrigin == InterCompanyOrigin::Derived)
            {
                ReqItemTable reqItemTable = ReqItemTable::metFindReqItemTable(this.ItemId, this.InventDimId);

                if (reqItemTable)
                {
                    this.PurchPrice = this.metGetUnitPriceForIntercompanyPurchLines(reqItemTable);
                    this.LineAmount = this.calcLineAmountForcedInteraction(fieldNum(PurchLine, PurchPrice));
                    return [this.PurchPrice, this.LineAmount];
                }
            }
        }

        return [0.00, 0.00];
        
    }

    /// <summary>
    /// Copy the new sales line (After substituted from IOM) to a new purch line on the reference PO.
    /// </summary>
    /// <param name = "_salesLineNew">Sales line</param>
    /// <returns>Purchase line</returns>
    public PurchLine copyToNewLineFromNewSalesLine(SalesLine _salesLineNew)
    {
        PurchTable              purchTable;
        PurchLine               purchLineNew, purchLineExisting;
        METPurchLine            metPurchLineNew, metPurchLineExisting;
        InventItemPurchSetup    purchSetup;

        purchTable              = PurchTable::find(_salesLineNew.METReplenishmentPOReference);
        purchLineExisting       = this.getExistingPurchLine(_salesLineNew, true);
        metPurchLineExisting    = purchLineExisting.metPurchLine();
        
        ttsbegin;
        buf2Buf(metPurchLineExisting, metPurchLineNew);

        metPurchLineExisting = METPurchLine::find(purchLineExisting.RecId, true);
        
        metPurchLineExisting.ChangeReasonCode = METVendParameters::find().POChangeReasonCode;;
        metPurchLineExisting.update();

        metPurchLineNew.PurchLine = 0;

        purchLineNew.initFromPurchTable(purchTable);
        purchLineNew.initFromPurchLine(purchLineExisting, true, true, true);

        purchLineNew.ItemId             = _salesLineNew.ItemId;
        purchLineNew.PackedExtensions   = conNull();
        purchLineNew.PurchUnit          = InventItemPurchSetup::find(purchLineNew.ItemId, purchLineNew.InventDimId).METPurchUnit;
        
        purchLineNew.itemIdChanged();
        purchLineNew.PurchQty = _salesLineNew.SalesQty;
        
        PurchLine::modifyPurchQty(purchLineNew, purchLineNew.inventDim(), false);
        
        purchLineNew.metPackMETPurchLine(metPurchLineNew);
        purchLineNew.LineAmount = 0;
        purchLineNew.PriceUnit  = 0;

        purchLineNew.createLine(true, false, false, false, false);

        ttscommit;

        METPurchaseOrderProcessHelper::confirmPurchaseOrder(purchTable.PurchId);

        return purchLineNew;
    }

    /// <summary>
    /// Get the existing purchase order line which was cancelled at the time of sales line substitution through IOM.
    /// </summary>
    /// <param name = "_salesLine">Sales line</param>
    /// <param name = "_getCanclledLine">Decides whether a cancelled line or open lines to be returned</param>
    /// <returns></returns>
    public PurchLine getExistingPurchLine(SalesLine _salesLine, boolean _getCanclledLine)
    {
        PurchLine   existingPurchLine, retPurchLine;

        if (!_getCanclledLine)
        {
            select firstonly existingPurchLine
                where existingPurchLine.PurchId == _salesLine.METReplenishmentPOReference
                && existingPurchLine.ItemId == _salesLine.ItemId
                && existingPurchLine.PurchUnit == _salesLine.SalesUnit
                && existingPurchLine.PurchStatus != PurchStatus::Canceled;

            if (existingPurchLine.RecId)
            {
                retPurchLine = existingPurchLine;
            }
        }
        else if (_getCanclledLine)
        {
            select firstonly existingPurchLine
                where existingPurchLine.PurchId == _salesLine.METReplenishmentPOReference
                && existingPurchLine.ItemId == _salesLine.ItemId
                && existingPurchLine.PurchUnit == _salesLine.SalesUnit
                && existingPurchLine.PurchStatus == PurchStatus::Canceled;

            if (existingPurchLine.RecId)
            {
                retPurchLine = existingPurchLine;
            }
        }

        return retPurchLine;
    }

    /// <summary>
    /// Substitute the reference PO line from a substituted sales line when done through IOM.
    /// </summary>
    public void metCancelPurchLineFromSalesLine()
    {
        PurchLine purchLine = PurchLine::findRecId(this.RecId);

        ttsbegin;
        purchLine.selectForUpdate(true);

        purchLine.RemainInventPhysical       = 0;
        purchLine.RemainPurchPhysical        = 0;
        purchLine.PdsCWRemainInventPhysical  = 0;
        purchLine.update();

        InventMovement::bufferSetRemainQty(purchLine);
        ttscommit;
    }

    /// <summary>
    /// Get the packing slip id from the referenced sales order.
    /// </summary>
    /// <param name = "_purchId"></param>
    /// <returns></returns>
    public static PackingSlipId getProductReceiptForReplenishmentOrder(PurchId _purchId)
    {
        SalesId         salesId;
        FormRun         formRun;
        PurchLine       purchLine;
        PurchParmLine   purchParmLine;
        PackingSlipId   packingSlipId;
        PurchParmTable  purchParmTable;
        CustPackingSlipJour custPackingSlipJour;

        select firstonly METReplenishmentSOReference from purchLine
            where purchLine.PurchId == _purchId
            && purchLine.PurchStatus == PurchStatus::Backorder
            && purchLine.METReplenishmentSOReference != '';

        if (purchLine.METReplenishmentSOReference)
        {
            changecompany(InventParameters::find().METInternalCustLegelEntity)
            {
                // Find the corresponding packing slip journal for the sales order.
                // We order by CreatedDateTime descending to get the latest one, but this can be adjusted.
                select firstonly PackingSlipId from custPackingSlipJour
                    where custPackingSlipJour.SalesId == purchLine.METReplenishmentSOReference;

                if (custPackingSlipJour.PackingSlipId)
                {
                    packingSlipId = custPackingSlipJour.PackingSlipId;
                }
            }
        }

        return packingSlipId;
    }

    /// <summary>
    /// Extension of PurchLine remove functionality to restrict deletion of confirmed PO lines
    /// and enforce ISP user business rules.
    /// </summary>
    /// <returns>
    /// True if the line can be deleted; otherwise, false.
    /// </returns>
    public boolean validateDelete(boolean _interCompanyForce)
    {
        boolean ret = next validateDelete(_interCompanyForce);

        // Custom rule: ISP users cannot delete confirmed lines
        PurchLineAllVersions purchLineAllVersions;
        PurchTableVersion    purchTableVersion;
        VendPurchOrderJour   vendPurchOrderJour;

        select firstonly RecId from purchLineAllVersions
            where purchLineAllVersions.InventTransId == this.InventTransId
        exists join purchTableVersion
             where purchTableVersion.RecId == purchLineAllVersions.PurchTableVersionRecId
        exists join vendPurchOrderJour
            where vendPurchOrderJour.PurchTableVersion == purchTableVersion.RecId;

        if (purchLineAllVersions.RecId)
        {
            ret = false;
        }

        return ret;
    }
